import{_ as l,l as r,o as e,c as h,v as t,p as n,x as o,d as s,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"生物芯片光刻","description":"","frontmatter":{"title":"生物芯片光刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/biochip-litho.md","filePath":"litho/biochip-litho.md","lastUpdated":1789023840000}'),c={name:"litho/biochip-litho.md"};function E(_,a,u,m,A,b){const i=r("Mermaid");return e(),h("div",null,[a[1]||(a[1]=t('<h1 id="生物芯片光刻" tabindex="-1">生物芯片光刻 <a class="header-anchor" href="#生物芯片光刻" aria-label="Permalink to &quot;生物芯片光刻&quot;">​</a></h1><div class="epigraph"><p>流道、微井和原位合成阵列用的是成熟紫外光刻与软光刻；规格源是生物兼容与封闭，不是 MMP。</p><footer>—— 对照 bioMEMS / lab-on-chip 光刻与 DNA 微阵列光导向合成的通称</footer></div><p><a href="/litho/two-photon-3d">上一课</a>给出研究用三维聚合物。缺口是生物实验室更常用的平面流程。本课钉生物芯片光刻。回到 EUV 源的替代概念，留给[下一课](/litho/fel-euv-source）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>微流控：SU-8 一类厚负胶、软光刻（PDMS 从光刻母模翻制）、玻璃/聚合物键合。DNA/肽阵列：光导向原位合成（光敏保护基 + 掩模或 DMD），分辨率在微米，化学步骤数是墙。与 IC 黄光间比：金属离子污染规格可能相反（要对生物友好），颗粒杀手定义按通道堵塞。</p><p>缺口是<strong>应用域换规格源</strong>，不是新光学。把生物芯片写进逻辑光刻附录会混五栏——本课明确它是替代形态课序里的应用。</p><h3 id="软光刻不是无光刻" tabindex="-1">软光刻不是无光刻 <a class="header-anchor" href="#软光刻不是无光刻" aria-label="Permalink to &quot;软光刻不是无光刻&quot;">​</a></h3><p>PDMS 翻制仍要一块光刻母版。母版可用激光直写或接触式。量产是翻制摊销母版，类似掩模摊销但材料不同。</p><p><span class="marginnote">原位合成的「套刻」是多次紫外对同一阵列的对准，化学残差比光学更毒。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选：接触式/直写做母模 → 翻制或直接胶器件。洁净：生物兼容清洗，避免 PFAS 课那种 IC 专用化学若被法规波及也要评估。计量：通道截面、泄漏，不是 CD-SEM 为主。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>厚负胶交联形成通道墙；键合封闭。阵列合成是空间上的保护基脱除，光学只提供地址。信息密度远低于 IC，步骤化学才是良率。</p>',13)),(e(),n(p,null,{default:o(()=>[d(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASTER%5B%22%E5%85%89%E5%88%BB%E6%AF%8D%E6%A8%A1%22%5D%20--%3E%20SOFT%5B%22PDMS%20%2F%20%E7%BF%BB%E5%88%B6%22%5D%0A%20%20UV%5B%22%E5%AF%BB%E5%9D%80%E7%B4%AB%E5%A4%96%22%5D%20--%3E%20ARR%5B%22%E5%8E%9F%E4%BD%8D%E5%90%88%E6%88%90%E9%98%B5%E5%88%97%22%5D%0A%20%20SOFT%20--%3E%20CHIP%5B%22%E6%B5%81%E6%8E%A7%E8%8A%AF%E7%89%87%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不讲临床法规。不把 CRISPR 或测序化学当光刻。本课不进入逻辑 fab 污染控制的全套 SEMI。</p><p>后课默认：生物应用用成熟紫外与翻制；下一课回到领先逻辑，问 FEL 能否当 EUV 源替代。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生物芯片光刻规格源是通道封闭与化学兼容，分辨率宽松。</li><li>软光刻摊销母模；阵列合成的墙在化学步数。</li><li>不并入逻辑 EUV 主干。</li><li>出处：bioMEMS 与光导向原位合成通称。</li></ul>',5))])}const B=l(c,[["render",E]]);export{S as __pageData,B as default};
